/**
 * The TypeScript must not fall behind the contract.
 *
 *   bun apps/app/src/lib/consult/contract.test.ts
 *
 * WHERE THE CONTRACT LIVES NOW
 *
 * It used to be `src/content/consult-contract.json`, generated by the backend's
 * `scripts/export_contract.py` from its Pydantic models. The GraphRAG migration
 * deleted those models, the generator went with them, and no auto-generated JSON
 * is coming back. So the hand-written `docs/api-contract.md` IS the contract,
 * and this suite reads the machine-readable block at the bottom of it.
 *
 * WHY THIS SUITE GOT BIGGER RATHER THAN SMALLER
 *
 * A generated file could not contradict itself. A hand-written one can: the
 * prose at the top and the JSON block at the bottom are edited by different
 * people at different times, and nothing but this file makes them agree. So the
 * `kind` table and the source-namespace table are parsed back OUT of the prose
 * and compared to the block. A document that disagrees with itself fails here
 * instead of in production, which is the guarantee the generator used to give.
 *
 * WHY THE ASSERTIONS ARE WRITTEN OUT BY HAND
 * TypeScript types do not exist at runtime, so nothing here can reflect over
 * `ConsultResult`. Instead each value the UI actually branches on is asserted
 * against the contract explicitly. That is narrower than a generated type — and
 * it is aimed at the failure that actually happens: the backend changes a phase
 * name or a source prefix, and the frontend keeps compiling while behaving
 * wrongly.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { CONSULTING, type ConsultKind, type ConsultPhase } from "./types";

const results: [string, boolean, string][] = [];
const check = (name: string, ok: boolean, detail = "") => {
  results.push([name, ok, detail]);
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? ` - ${detail}` : ""}`);
};

const same = (a: string[], b: string[]) =>
  a.length === b.length && [...a].sort().join("|") === [...b].sort().join("|");

// Resolved from THIS FILE, not the working directory. The README runs this from
// the repo root and `bun run test` runs it from apps/app; a cwd-relative path
// works in one and throws ENOENT in the other.
// `import.meta.dir` would be shorter but is a Bun extension that does not
// typecheck, and `new URL(".", import.meta.url).pathname` gets Windows drive
// letters wrong. fileURLToPath is the spelling that is correct on both.
const DOC_PATH = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../../../../docs/api-contract.md",
);
const markdown = readFileSync(DOC_PATH, "utf8");

// --- the machine-readable block ----------------------------------------------
const fenced = markdown.match(/```json contract\r?\n([\s\S]*?)```/);
if (!fenced?.[1]) {
  console.error(
    "FAIL  docs/api-contract.md has no `json contract` block.\n" +
      "      That block is the contract this suite checks against. If it was\n" +
      "      renamed or removed, restore it rather than deleting this test.",
  );
  process.exit(1);
}

type Contract = {
  enums: { kind: string[]; phase: string[] };
  phase_groups: { consulting: string[]; legacy: string[] };
  source_namespaces: string[];
  request_fields: string[];
  result_fields: string[];
  context_fields: string[];
  upload_fields: string[];
  caps: Record<string, number | string>;
};

let contract: Contract;
try {
  contract = JSON.parse(fenced[1]) as Contract;
} catch (error) {
  console.error(`FAIL  the contract block is not valid JSON: ${(error as Error).message}`);
  process.exit(1);
}

/**
 * Pull the first-column keys out of a markdown table.
 *
 * Used to read the PROSE back and compare it to the block. Anchored on the
 * table's header row so a backticked value appearing anywhere else in the
 * document cannot be mistaken for a row of this one.
 */
function tableKeys(headerRow: string): string[] {
  const start = markdown.indexOf(headerRow);
  if (start === -1) return [];
  const rest = markdown.slice(start + headerRow.length).split(/\r?\n/);
  const keys: string[] = [];
  for (const line of rest) {
    if (!line.startsWith("|")) {
      if (keys.length) break; // the table has ended
      continue; // still on the |---|---| separator
    }
    const cell = line.match(/^\|\s*`([^`]+)`/);
    if (cell?.[1]) keys.push(cell[1].replace(/:$/, ""));
  }
  return keys;
}

// --- the unions the UI branches on -------------------------------------------
// Written out as literal arrays because the type itself is erased at runtime. If
// someone edits the union in types.ts they must edit these too, and the test then
// tells them whether the contract agrees.
const TS_KINDS: ConsultKind[] = ["chat", "intake", "answer", "escalation", "error"];
const TS_PHASES: ConsultPhase[] = [
  "idle",
  "greeted",
  "casual",
  "gathering",
  "collecting",
  "choosing",
  "completed",
];

check(
  "ConsultKind matches the contract exactly",
  same(TS_KINDS, contract.enums.kind),
  `ts=[${TS_KINDS}] doc=[${contract.enums.kind}]`,
);
check(
  "ConsultPhase matches the contract exactly",
  same(TS_PHASES, contract.enums.phase),
  `ts=[${TS_PHASES}] doc=[${contract.enums.phase}]`,
);

// The single easiest thing to get wrong, and the most expensive: send `problem`
// while a consultation is open and every follow-up starts a new one.
check(
  "CONSULTING matches the contract's phase group",
  same([...CONSULTING], contract.phase_groups.consulting),
  `ts=[${CONSULTING}] doc=[${contract.phase_groups.consulting}]`,
);

// Retired, but a conversation persisted before the card intake was removed still
// carries one. Dropping them from the union makes `load_context` reset the chat.
check(
  "the retired card phases are still in the TS union",
  contract.phase_groups.legacy.every((p) => (TS_PHASES as string[]).includes(p)),
  contract.phase_groups.legacy.join(", "),
);

// --- fields the UI reads without guarding ------------------------------------
for (const field of [
  "kind",
  "condition",
  "message",
  "answer",
  "intake",
  "context",
  "sources",
  "documentTruncated",
]) {
  check(`ConsultResult.${field} is in the contract`, contract.result_fields.includes(field));
}

for (const field of ["phase", "chat_history", "language", "condition", "symptoms"]) {
  check(`ConsultContext.${field} is in the contract`, contract.context_fields.includes(field));
}

// --- request side --------------------------------------------------------------
// `documents` is load-bearing now: the backend stores no uploads, so a turn
// without it is a turn where the assistant cannot see the attached reports.
for (const field of [
  "problem",
  "freeText",
  "context",
  "conversationId",
  "documents",
  "bot_id",
]) {
  check(`the backend accepts ${field}`, contract.request_fields.includes(field));
}

// Retired with the list. It carried ONE retrieval budget for every attachment
// joined together, so the second and third were silently dropped — and a client
// that rebuilds the string by hand rebuilds exactly that bug. Asserted gone by
// name for the same reason `indexed` is.
check(
  "the retired `documentText` field is gone",
  !contract.request_fields.includes("documentText"),
);

// --- upload side ---------------------------------------------------------------
// `indexed` is RETIRED, and is asserted gone by name. A client still testing
// `result.indexed > 0` evaluates `undefined > 0` — always false — and reports
// every successful upload as unreadable. That shipped once.
const TS_UPLOAD_FIELDS = ["filename", "chars", "text", "truncated"];
check(
  "UploadResult matches the contract exactly",
  same(TS_UPLOAD_FIELDS, contract.upload_fields),
  `ts=[${TS_UPLOAD_FIELDS}] doc=[${contract.upload_fields}]`,
);
check("the retired `indexed` field is gone", !contract.upload_fields.includes("indexed"));

// --- citations ----------------------------------------------------------------
// answer-sources.tsx groups on these prefixes. A namespace the backend adds that
// the UI does not know falls into the "knowledge" bucket and is then miscounted as
// a curated Ayurveda note — a false claim about where an answer came from.
const UI_NAMESPACES = ["knowledge", "report", "graphrag", "memory"];
check(
  "every source namespace the contract emits is handled by the UI",
  same(UI_NAMESPACES, contract.source_namespaces),
  `ui=[${UI_NAMESPACES}] doc=[${contract.source_namespaces}]`,
);

// --- the document must not contradict itself -----------------------------------
// The block is hand-written and sits ~150 lines below the prose it summarises.
// Nothing but these two checks keeps them honest.
const proseKinds = tableKeys("| `kind` | What it is | How to render |");
check(
  "the prose `kind` table agrees with the contract block",
  same(proseKinds, contract.enums.kind),
  `prose=[${proseKinds}] block=[${contract.enums.kind}]`,
);

const proseNamespaces = tableKeys("| Prefix | Meaning |");
check(
  "the prose source-namespace table agrees with the contract block",
  same(proseNamespaces, contract.source_namespaces),
  `prose=[${proseNamespaces}] block=[${contract.source_namespaces}]`,
);

// --- the caps a client must NOT re-implement -----------------------------------
// Recorded so the numbers have one home. The client deliberately does not trim:
// pre-trimming guesses at a budget it does not own and silently drops text the
// backend would have kept.
check(
  "the extraction cap is documented",
  typeof contract.caps.upload_extract_chars === "number",
  `${contract.caps.upload_extract_chars} chars`,
);
check(
  "the retrieval cap is documented",
  typeof contract.caps.consult_retrieval_chars_per_query === "number",
  `${contract.caps.consult_retrieval_chars_per_query} chars per query`,
);

const passed = results.filter(([, ok]) => ok).length;
console.log(`\n===== contract (frontend): ${passed}/${results.length} passed =====`);
if (passed !== results.length) {
  console.log("\nFailing:");
  for (const [name, ok, detail] of results) if (!ok) console.log(`  - ${name}: ${detail}`);
}
process.exit(passed === results.length ? 0 : 1);
